<script setup lang="ts">
import {computed, onBeforeUnmount, ref} from 'vue';import {useRoute} from 'vue-router';import {fetchHttpClient, ApiHttpError} from '../../api/client';import {mockApi} from '../../api/mock';import FieldMapping from './FieldMapping.vue';import DatasetList from './DatasetList.vue';import ImportHealth from './ImportHealth.vue';
const route=useRoute();const projectId=computed(()=>String(route.params.p));const client=import.meta.env.VITE_USE_MOCK !== 'false' ? mockApi : fetchHttpClient();const abortController=new AbortController();const file=ref<File|null>(null),step=ref(1),busy=ref(false),error=ref('');onBeforeUnmount(()=>abortController.abort());
function choose(e:Event){const f=(e.target as HTMLInputElement).files?.[0]??null;error.value='';if(f&&!/\.(csv|xlsx|xls|txt)$/i.test(f.name)){error.value='��֧�� CSV��XLSX��XLS �� TXT �ļ�';return}if(f&&f.size>20*1024*1024){error.value='�ļ���С���ܳ��� 20 MB';return}file.value=f}
async function upload(){if(!file.value){error.value='��ѡ��Ҫ������ļ�';return}busy.value=true;try{const d=await client.upload(projectId.value,file.value,abortController.signal);sessionStorage.setItem(`voicelens:dataset:${projectId.value}`,JSON.stringify(d));step.value=2}catch{error.value='�ϴ�ʧ�ܣ����Ժ�����'}finally{busy.value=false}}
</script>
<template><section class="page" data-testid="import-page"><h1>���ݵ���</h1><p class="muted">��Ŀ��{{projectId}}</p><div class="steps">�����ļ� �� �ֶ�ӳ�� �� ��������</div><div v-if="step===1" class="card"><input data-testid="file-input" type="file" accept=".csv,.xlsx,.xls,.txt" @change="choose"><p v-if="file">{{file.name}}</p><button data-testid="upload-button" :disabled="busy" @click="upload">{{busy?'�ϴ��С�':'��ʼ�ϴ�'}}</button><p v-if="error" class="error" data-testid="import-error">{{error}}</p></div><FieldMapping v-else-if="step===2" @next="step=3"/><ImportHealth v-else @done="step=1"/><DatasetList :project-id="projectId"/></section></template>
